  ('85631e66-44f3-3ecd-8cbd-3fd16f525b13', 'f9948630-7d9d-3976-b23a-17f13c07d907', 7, 'cloze', 'A: Are you from Vietnam?  B: No, I''m ___. I''m from Haiti.', 0.5, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('61e78684-bc0a-3f4c-b03f-1f0f06d5064b', 'f9948630-7d9d-3976-b23a-17f13c07d907', 8, 'translation', '[L1: Say it in English: ''No soy profesora. Soy estudiante.'']', 0.5, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('390c928c-2668-3eb7-b178-615182667088', 'f9948630-7d9d-3976-b23a-17f13c07d907', 9, 'speaking', '[audio] ''Are you a teacher?'' → [L1: Answer truthfully with a short answer, then say what you are.]', 0.6, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('9feb0987-a71d-3a49-a60c-1e9a0e9b88d2', 'f9948630-7d9d-3976-b23a-17f13c07d907', 10, 'dialogue', '[L1: The AI has wrong ideas about you — your name, your country, what you are. Listen, correct each one with a negative, then say what is true.]', 0.6, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('08515ab2-5f48-395c-ac0c-fd1926ee2475', '22afcd0f-bbe4-3add-aa93-3f08e69b3252', 1, 'flashcard', 'Are you…? · Is she…? · Am I…? · Yes, I am. · No, I''m not.', 0.1, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('558a754c-2c07-305d-9c1d-8de2449ee3d7', '22afcd0f-bbe4-3add-aa93-3f08e69b3252', 2, 'listening_mc', '[audio, 1.0x] ''You''re a student.'' … ''Are you a student?'' — [L1: Which one is the question?]', 0.2, 'receptive', 'human-authored/phase0-slice', 'draft'),
  ('3b19dfaf-20aa-3c86-97a2-37facf0aa0aa', '22afcd0f-bbe4-3add-aa93-3f08e69b3252', 3, 'ordering', '[L1: Put the words in order to make a question.]', 0.4, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('b84e1533-3763-3160-8577-8b6a8c629d64', '22afcd0f-bbe4-3add-aa93-3f08e69b3252', 4, 'cloze', '___ she your teacher?', 0.4, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('6307c606-de84-3d33-a530-eb649705ff2b', '22afcd0f-bbe4-3add-aa93-3f08e69b3252', 5, 'matching', '[L1: Match each question to its short answer.]', 0.4, 'receptive', 'human-authored/phase0-slice', 'draft'),
  ('f18f41c9-193a-3144-803e-2edd838de59a', '22afcd0f-bbe4-3add-aa93-3f08e69b3252', 6, 'listening_mc', '[audio, 0.75x] ''Is your class in the morning?'' — [L1: Choose the correct answer.]', 0.5, 'receptive', 'human-authored/phase0-slice', 'draft'),
  ('4f13c619-087a-3b43-8a24-a4f5735783f8', '22afcd0f-bbe4-3add-aa93-3f08e69b3252', 7, 'translation', '[L1: Ask it in English: ''¿Eres estudiante?'']', 0.5, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('e80f3461-adfb-3e14-a91e-5a10ea54efd4', '22afcd0f-bbe4-3add-aa93-3f08e69b3252', 8, 'speaking', '[L1: Ask the AI if it is from your country. Start with Are, and make your voice go up at the end.]', 0.5, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('e29b44ea-f26c-3103-90cf-326a2f49bf88', '22afcd0f-bbe4-3add-aa93-3f08e69b3252', 9, 'dialogue', '[L1: Guessing game. The AI is thinking of a country you know and of what it is (student or teacher). Ask only yes/no questions with Are you / Is it, then guess.]', 0.6, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('edd15c89-2690-34fc-a481-b65e52d5f6c3', 'ee4de8f1-dd22-3abb-a76c-acb1ed3eedd9', 1, 'flashcard', 'what · where · who · What''s your name? · Where are you from?', 0.1, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('502ce563-e05a-309e-9c6b-d9e48d93eecd', 'ee4de8f1-dd22-3abb-a76c-acb1ed3eedd9', 2, 'matching', '[L1: Match each question to its answer.]', 0.3, 'receptive', 'human-authored/phase0-slice', 'draft'),
  ('1c75667d-55b6-38e7-9e24-b0efd4885bd8', 'ee4de8f1-dd22-3abb-a76c-acb1ed3eedd9', 3, 'listening_mc', '[audio, 0.75x] ''Where is she from?'' — [L1: What does the speaker want to know?]', 0.4, 'receptive', 'human-authored/phase0-slice', 'draft'),
  ('6d942c29-9023-34e3-8a33-8da00ca83750', 'ee4de8f1-dd22-3abb-a76c-acb1ed3eedd9', 4, 'cloze', 'A: ___ is your teacher?  B: My teacher is Ana.  A: ___ is she from?  B: She''s from Brazil.', 0.4, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('9fa45904-7f43-329e-84c5-349474a9ee43', 'ee4de8f1-dd22-3abb-a76c-acb1ed3eedd9', 5, 'ordering', '[L1: Put the words in order.]', 0.4, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('54bc890b-1d85-3a04-8655-b9932f758565', 'ee4de8f1-dd22-3abb-a76c-acb1ed3eedd9', 6, 'listening_mc', '[audio, 1.0x] ''Where are you from?'' — [L1: At the end, does the voice go up or down?]', 0.5, 'receptive', 'human-authored/phase0-slice', 'draft'),
  ('c4cb8a06-708c-3ba3-949c-d8e6c9d0633b', 'ee4de8f1-dd22-3abb-a76c-acb1ed3eedd9', 7, 'translation', '[L1: Ask it in English: ''¿Quién es tu profesora?'']', 0.5, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('a326de97-31ce-3ba1-b343-0248e8ab1275', 'ee4de8f1-dd22-3abb-a76c-acb1ed3eedd9', 8, 'speaking', '[L1: Ask the AI about its country: ask with where, and let your voice fall at the end.]', 0.5, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('5e4590b4-2c30-354b-bf54-890ec07e41db', 'ee4de8f1-dd22-3abb-a76c-acb1ed3eedd9', 9, 'dialogue', '[L1: Interview the AI: ask its name, its country, and who its teacher is. Then the AI asks you the same three questions — answer them.]', 0.6, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('4f84eed7-8b08-32c9-8cb8-d00da9164ae5', '43296b44-a09c-3c84-ada9-af9ada73b4dd', 1, 'flashcard', 'twenty-one · thirty · forty · fifty · sixty · seventy · eighty · ninety · one hundred', 0.1, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('054bd0bf-119b-3189-afd1-43cd17ba0637', '43296b44-a09c-3c84-ada9-af9ada73b4dd', 2, 'listening_mc', '[audio, 1.0x] ''thirteen'' — [L1: Which number did you hear?]', 0.3, 'receptive', 'human-authored/phase0-slice', 'draft'),
  ('54d24cf2-04df-3db2-9120-2bca46958f94', '43296b44-a09c-3c84-ada9-af9ada73b4dd', 3, 'matching', '[L1: Match the figures to the words.]', 0.3, 'receptive', 'human-authored/phase0-slice', 'draft'),
  ('58df8fc4-d3ca-3928-a9cf-036317765b64', '43296b44-a09c-3c84-ada9-af9ada73b4dd', 4, 'cloze', 'twenty, ___ , forty, fifty, ___ , seventy', 0.4, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('5ed4977d-e0a2-3047-9cb5-d4438f3392bf', '43296b44-a09c-3c84-ada9-af9ada73b4dd', 5, 'ordering', '[L1: Put the words in order to make the question.]', 0.4, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('b772a4bd-aed8-3d8c-af1f-a0388f945fc1', '43296b44-a09c-3c84-ada9-af9ada73b4dd', 6, 'listening_mc', '[audio, 0.75x] ''My phone number is five five five, two eight, nine one.'' — [L1: Which number do you write?]', 0.5, 'receptive', 'human-authored/phase0-slice', 'draft'),
  ('62addb48-ddc1-36f3-af7b-8ac5140018bd', '43296b44-a09c-3c84-ada9-af9ada73b4dd', 7, 'dictation', '[audio, 2 plays: 0.75x then 1.0x] ''My phone number is five five zero, nine two.''', 0.5, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('bd4d2110-f0b5-3a6b-9556-72ce622a7663', '43296b44-a09c-3c84-ada9-af9ada73b4dd', 8, 'listening_mc', '[audio, 1.0x] ''Fifteen students are in my class.'' — [L1: How many students?]', 0.5, 'receptive', 'human-authored/phase0-slice', 'draft'),
  ('132ecee2-a63e-382d-baf0-1f43e6b2d77b', '43296b44-a09c-3c84-ada9-af9ada73b4dd', 9, 'speaking', '[L1: Say your phone number digit by digit, in small groups, with a short pause between groups.]', 0.5, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('c077eec9-71ff-34bf-9bc7-1f572ef05254', '43296b44-a09c-3c84-ada9-af9ada73b4dd', 10, 'dialogue', '[L1: Exchange phone numbers with the AI: ask with What''s your phone number?, write down its answer, say your own number digit by digit, and repeat the AI''s number back to check it.]', 0.6, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('a916c715-7782-31e0-a6fe-2a3a96d6902b', '7ab7e4ce-b4fb-36fc-8bc6-6ef97586f5f0', 1, 'flashcard', 'first name · last name · email address · form · Mr · Ms', 0.1, 'productive', 'human-authored/phase0-slice', 'draft'),
  ('c8807a9b-a32f-3c28-b5e2-5fd4605c6e42', '7ab7e4ce-b4fb-36fc-8bc6-6ef97586f5f0', 2, 'matching', '[L1: Match the spoken question to the form field.]', 0.3, 'receptive', 'human-authored/phase0-slice', 'draft'),
  ('1f3c9a50-3c0d-3d6a-a4dd-3d816cc7967d', '7ab7e4ce-b4fb-36fc-8bc6-6ef97586f5f0', 3, 'matching', '[L1: What kind of information is each of these? Match it to the field.]', 0.3, 'receptive', 'human-authored/phase0-slice', 'draft'),
  ('cc7f8e82-5424-31ee-b737-5af79a1a5b62', '7ab7e4ce-b4fb-36fc-8bc6-6ef97586f5f0', 4, 'cloze', 'Form
INSERT INTO public.exercise_options (id, exercise_id, label, is_correct, position, rationale) VALUES
  ('84610a0b-b6e6-333e-973f-9deca273ff4f', 'd816db14-d539-3531-9eb3-2f7598ff83f0', '[L1: Leaving — it is a farewell.]', true, 1, '''Good night'' is said only when leaving or going to bed.'),
  ('473085b9-59de-38ed-aba9-257ecb60f31a', 'd816db14-d539-3531-9eb3-2f7598ff83f0', '[L1: Arriving — it is a greeting.]', false, 2, 'Direct es transfer: ''buenas noches'' greets AND takes leave; English splits this into ''good evening'' (greet) vs ''good night'' (leave).'),
  ('47ef9a25-5656-38ea-a0fe-39403fe717fe', '59dd2a75-e064-3613-bdf1-9381e25933bc', 'Hello!', true, 1, 'Neutral and safe with a teacher or any new person.'),
  ('da2ed153-58d9-33c3-b6ac-7932305f045e', '59dd2a75-e064-3613-bdf1-9381e25933bc', 'Hi!', false, 2, 'Not wrong, but informal — best kept for friends; the item trains noticing the register pair.'),
  ('59fa6a5d-b872-325c-8965-279e284284d1', '59dd2a75-e064-3613-bdf1-9381e25933bc', 'Bye!', false, 3, 'A farewell, not a greeting — catches learners matching sound (short, friendly) instead of function.'),
  ('a1720417-ef38-3392-8dcc-22475252c1bc', 'bf1e35f1-b976-3d00-9431-13b6e3d787ce', 'Goodbye!', true, 1, 'Two syllables, starts with ''good-'' and ends in ''-bye''.'),
  ('a6754bc2-32a9-3d03-9323-09c8ab4750f0', 'bf1e35f1-b976-3d00-9431-13b6e3d787ce', 'Good night!', false, 2, 'Also starts with ''good-''; catches learners who stop listening after the first syllable.'),
  ('a31eea24-4d13-35ad-a159-e3627ea949e8', 'bf1e35f1-b976-3d00-9431-13b6e3d787ce', 'Bye!', false, 3, 'The short register pair of the same word; forces hearing the ''good-'' syllable.'),
  ('cce3b188-2768-3596-a0db-5d7292c4cbda', '9cc1c9ce-c6ec-3670-b689-4d4a1f087ed8', 'E', true, 1, 'English E is named /iː/ — like the es letter ''i''.'),
  ('e52b6595-731b-37b6-ac4d-4afb74c5c8fa', '9cc1c9ce-c6ec-3670-b689-4d4a1f087ed8', 'I', false, 2, 'es transfer: learners map the /iː/ sound to their letter ''i''. English I is named /aɪ/.'),
  ('78e5caef-1ffe-39b3-a04a-79f81d1a9df2', '9cc1c9ce-c6ec-3670-b689-4d4a1f087ed8', 'A', false, 3, 'English A is named /eɪ/, which es ears parse as ''ei'' — the second member of the same confusion triangle.'),
  ('7b2ace33-2c40-32d5-825e-d10454e5b64a', 'bf1222a5-0051-32f5-9e85-b95732d33e16', 'G', true, 1, 'Named /dʒiː/ — consonant /dʒ/ + the E-vowel from ex 2.'),
  ('b4fa5f0d-d4ee-352b-b5ca-1505a38c1311', 'bf1222a5-0051-32f5-9e85-b95732d33e16', 'J', false, 2, 'Named /dʒeɪ/ — same consonant, different vowel; es speakers often swap the two names wholesale.'),
  ('0142a601-7eaa-3cea-98bd-f9bb3bfe6d24', 'ed55c4b5-c3d3-3d68-835b-06a60acff283', 'hello', true, 1, 'Five letters, with the double L heard as ''L-L''.'),
  ('6f4dec93-27d2-36c5-84d3-58b1a619e9ce', 'ed55c4b5-c3d3-3d68-835b-06a60acff283', 'hi', false, 2, 'Same meaning, wrong form — catches learners who guess from context instead of decoding the letters.'),
  ('8ef7cb81-2bc8-311b-97f6-f4112e207fd8', 'efcda12d-2ef2-3b57-88b3-a13823bd80f8', 'What''s your name?', true, 1, 'The question asks for a name.'),
  ('994d800f-d5c4-33ab-9052-a95ab906ac7f', 'efcda12d-2ef2-3b57-88b3-a13823bd80f8', 'Nice to meet you.', false, 2, 'Also said at first meetings — forces listening for the question form, not the situation.'),
  ('c9370e13-47de-38a4-ad7a-ea5001f72951', 'efcda12d-2ef2-3b57-88b3-a13823bd80f8', 'Goodbye!', false, 3, 'A farewell; catches learners who answer from the greeting ''Hello'' without processing the question.'),
  ('c6d65105-60e6-3d4d-a8c9-326c3ca24879', 'db786599-5403-34e6-9dc6-e597951dc5b2', 'Hi, Tom! Nice to meet you.', true, 1, 'Greets back and closes the first-meeting pair.'),
  ('e2740b9c-8cd9-34be-b369-fbe155744aa7', 'db786599-5403-34e6-9dc6-e597951dc5b2', 'Goodbye, Tom!', false, 2, 'A farewell in an opening slot — function confusion recycled from L01.'),
  ('dd5c6c99-e724-3e20-a4c1-4b4c54fd0664', 'db786599-5403-34e6-9dc6-e597951dc5b2', 'What''s my name?', false, 3, 'my/your pronoun flip — a frequent early error when chunks are memorized without the pronoun analyzed.'),
  ('f6923da5-c5cf-3208-a6a5-6a9bd576f104', '7a791b3f-a3c0-36ff-9529-846de19d3bcf', 'sixteen', true, 1, 'Two syllables with stress on ''-teen''.'),
  ('2e3bd426-7c9c-3d20-88fa-a38962366178', '7a791b3f-a3c0-36ff-9529-846de19d3bcf', 'six', false, 2, 'One syllable — catches listeners who drop the unstressed-looking final syllable.'),
  ('cc1bf78f-92a3-3cd6-8d70-ce482335b89f', '7a791b3f-a3c0-36ff-9529-846de19d3bcf', 'fifteen', false, 3, 'Same ''-teen'' ending; forces hearing the first syllable, not just the suffix.'),
  ('1ba775e8-0707-35c4-99d1-e3c940cee752', 'e5046deb-a2f7-3b31-9ddb-1d23746b69eb', 'eleven', true, 1, 'Heard after ''I''m'' — three syllables, stress on -le-.'),
  ('f96fe0d5-6c78-3211-80e5-87a4a0d811ad', 'e5046deb-a2f7-3b31-9ddb-1d23746b69eb', 'seven', false, 2, 'Rhymes with eleven; catches listeners who miss the unstressed first syllable in connected speech.'),
  ('976cd5f6-2456-31b8-8d82-b033be98959c', 'e5046deb-a2f7-3b31-9ddb-1d23746b69eb', 'ten', false, 3, 'Shares the /en/ ending only — checks the learner is not matching final sounds alone.'),
  ('78e54f2f-0dcc-3cff-9b64-c0ab974b120f', '5cdc9895-3700-31d7-b6f9-459d18373719', 'Mexico', true, 1, 'Heard after ''from''.'),
  ('60d46d59-4d09-36be-a205-43aa76bcd3f1', '5cdc9895-3700-31d7-b6f9-459d18373719', 'Brazil', false, 2, 'Distractor: also taught this lesson; forces listening, not guessing.'),
  ('345d4be3-7a2c-30f4-ab7c-0ace837de7ae', '5cdc9895-3700-31d7-b6f9-459d18373719', 'She''s', false, 3, 'Catches learners matching first word heard, not meaning.'),
  ('88e45c8e-0c09-3291-b7cb-cf735c239011', '16a1df19-0982-3034-9694-003844262861', 'Where are you from?', true, 1, '''Where''re'' is the reduced form of ''Where are''.'),
  ('5eca30c7-bbdd-3dd2-88c5-fd634fbb3078', '16a1df19-0982-3034-9694-003844262861', 'Where you from?', false, 2, 'The ''re is quiet but present — trains hearing reductions (P6 preview).'),
  ('177b2fcb-f62e-3bc7-9ae0-aae0734063f7', 'ff4075ca-bdd5-3767-a27c-5733477eef21', 'Mexican', true, 1, 'The -an adjective form that follows ''She''s'' directly, with no ''from''.'),
  ('253e9b09-3b94-3335-9636-9e91fb06b274', 'ff4075ca-bdd5-3767-a27c-5733477eef21', 'Mexico', false, 2, 'The country — used with ''from''; catches learners treating the two forms as interchangeable.'),
  ('ade2e859-f6f5-3b88-b938-60b33ce46cb9', '921243c4-e3bc-3640-9df9-1a3da485b6dc', 'English', true, 1, 'Heard after ''I speak'' in the answer turn.'),
  ('08cd7e12-d22c-364c-b3a2-a2497048b4b4', '921243c4-e3bc-3640-9df9-1a3da485b6dc', 'Chinese', false, 2, 'Heard only in the question — catches keyword-matching across turns without processing ''No, I don''t.'''),
  ('82475a9c-491c-3966-9122-cbfe20d1bbb1', '002d2401-2d20-3fd6-a9ce-ed9adf2ffdb0', 'She is a teacher.', true, 1, 'is links she and teacher; it is short and unstressed but always there.'),
  ('93f52ad5-21ef-3909-9722-2baeaf3d79e8', '002d2401-2d20-3fd6-a9ce-ed9adf2ffdb0', 'She a teacher.', false, 2, 'Zero-copula transfer (ar/zh/vi): the learner''s L1 pattern without be — trains noticing the missing is.'),
  ('daced6ed-03f9-37d7-86fb-301eadacde90', '002d2401-2d20-3fd6-a9ce-ed9adf2ffdb0', 'She are a teacher.', false, 3, 'Agreement error: catches learners who hear that a be-word is present but not which one.'),
  ('eb1e98e9-54cc-33a0-97d4-1d0f99e4a201', 'e0f6cf06-ab0e-3cf6-88de-3a61b10b88aa', 'We are students.', true, 1, 'are with we, and a final -s on students — both are easy to miss at natural speed.'),
  ('821e6303-9c64-37e5-baee-121388790608', 'e0f6cf06-ab0e-3cf6-88de-3a61b10b88aa', 'We are student.', false, 2, 'Misses the plural -s: the exact segment vi/zh speakers tend to delete when listening and speaking.'),
  ('d7b754a0-8e0e-39c2-aa47-98a8dfd9483a', 'e0f6cf06-ab0e-3cf6-88de-3a61b10b88aa', 'I am a student.', false, 3, 'Person confusion: catches learners matching the familiar chunk instead of the subject they heard.'),
  ('2a36196e-a08f-38b5-8bf4-61ead799cf40', '005b0ac9-cd47-34db-b45b-db10311ed962', 'A student.', true, 1, 'not negates teacher; the second sentence states the fact.'),
  ('f33e451e-63f9-36f3-944c-b452214eae03', '005b0ac9-cd47-34db-b45b-db10311ed962', 'A teacher.', false, 2, 'Hears the noun but misses not — the exact miscomprehension this exercise trains against.'),
  ('beaa1181-bdd5-3596-a5a7-fd910887d40c', '005b0ac9-cd47-34db-b45b-db10311ed962', 'A new student.', false, 3, 'Adds information that was never said; catches guessing from known words instead of listening.'),
  ('7cc2060f-2927-3464-9522-d493306c2bed', '61cbfa06-490c-3b79-8ffe-a77296e9b268', 'Yes, I am.', true, 1, 'Affirmative short answers use the full, stressed form am — a sentence cannot end in I''m.'),
  ('603e4a25-5e6a-3e74-9138-fc17421773d5', '61cbfa06-490c-3b79-8ffe-a77296e9b268', 'Yes, I''m.', false, 2, 'The classic error: contractions are never sentence-final in English — this is the trap the lesson exists to defuse.'),
  ('523d849c-823f-345b-add9-cebb5f32bd67', '61cbfa06-490c-3b79-8ffe-a77296e9b268', 'Yes, I are.', false, 3, 'Agreement error under question pressure: are is copied from the question instead of switching to am.'),
  ('0f946727-0537-30d3-b96e-a81f820f299f', '558a754c-2c07-305d-9c1d-8de2449ee3d7', 'Are you a student?', true, 1, 'are moves to the front and the voice rises at the end — both signals mark the question.'),
  ('5141bda0-011d-38a0-9164-3ebcfb2d335c', '558a754c-2c07-305d-9c1d-8de2449ee3d7', 'You''re a student.', false, 2, 'Same words, statement order, falling voice: catches learners relying on words instead of order and melody.'),
  ('6726db1c-5acb-385b-bfeb-72f3a8a0c81e', 'f18f41c9-193a-3144-803e-2edd838de59a', 'Yes, it is.', true, 1, 'it stands for your class; is echoes the question''s be-form — pronoun plus full form.'),
  ('bf4d4921-379a-3407-8d47-8f1a01d34437', 'f18f41c9-193a-3144-803e-2edd838de59a', 'Yes, is.', false, 2, 'Pronoun drop (es ''Sí, es''): English short answers always need the subject pronoun.'),
  ('a71a6577-8141-3d62-9cad-3d91194ffb8d', 'f18f41c9-193a-3144-803e-2edd838de59a', 'Yes, it''s.', false, 3, 'Sentence-final contraction — recycles the L08 trap in the new it-frame to check the rule generalized.'),
  ('ee8ded2f-1f2c-31cb-aa03-d48f4e9b8b27', '1c75667d-55b6-38e7-9e24-b0efd4885bd8', 'A country.', true, 1, 'where asks about a place — here, the country she is from.'),
  ('28574802-fe4a-3065-bddc-73200a062ff8', '1c75667d-55b6-38e7-9e24-b0efd4885bd8', 'A name.', false, 2, 'Transfers from the more familiar What''s-your-name chunk; catches frame-matching instead of WH-word listening.'),
  ('9df07144-bf2c-358b-91fe-acb7a5d86729', '1c75667d-55b6-38e7-9e24-b0efd4885bd8', 'A language.', false, 3, 'Plausible topic from L06 conversations; forces attention to where, not to the general topic of introductions.'),
  ('e372219a-e240-37a9-8e1e-996fbe09f253', '54bc890b-1d85-3a04-8655-b9932f758565', 'Down.', true, 1, 'WH-questions end with falling intonation — the WH-word already signals the question.'),
  ('d8b960d0-6398-3e39-a94b-b6042ef2923a', '54bc890b-1d85-3a04-8655-b9932f758565', 'Up.', false, 2, 'Transfer from the L09 yes/no melody (and from zh/vi question rises); rising WH-questions sound like disbelief in English.'),
  ('e3cdb91c-926d-3dd1-b64f-f26f9a9cf2c5', '054bd0bf-119b-3189-afd1-43cd17ba0637', 'Thirteen.', true, 1, 'Stress on the second syllable: thir-TEEN.'),
  ('caecad5e-b350-3702-b696-e124d0a5e893', '054bd0bf-119b-3189-afd1-43cd17ba0637', 'Thirty.', false, 2, 'Stress on the first syllable: THIR-ty — the classic pair; listeners using vowel length alone (es/vi) fall here.'),
  ('f6929226-a6c1-37a4-a1c9-07765ba3bede', 'b772a4bd-aed8-3d8c-af1f-a0388f945fc1', '555-2891', true, 1, 'Three groups with pauses: five five five — two eight — nine one.'),
  ('f683d79d-6643-355d-8a1f-cc6502927210', 'b772a4bd-aed8-3d8c-af1f-a0388f945fc1', '555-2871', false, 2, 'One digit off in the middle group: catches listeners who stop checking after the first group.'),
  ('73329b0d-2ae7-35e6-9313-7275dca8e975', 'b772a4bd-aed8-3d8c-af1f-a0388f945fc1', '555-2819', false, 3, 'Last two digits reversed: catches holding digits as a pair without their order.'),
  ('a1025b43-8ab9-3cda-9725-10b253ef84db', 'bd4d2110-f0b5-3a6b-9556-72ce622a7663', '15', true, 1, 'fif-TEEN: final-syllable stress marks the teen.'),
  ('b7e7a54d-5d25-3095-a57f-cdb86bb2a005', 'bd4d2110-f0b5-3a6b-9556-72ce622a7663', '50', false, 2, 'FIF-ty: initial stress — the mirror error of ex2, now under sentence prosody.'),
  ('1b0271ac-c844-3028-b297-1064603e2dca', '6d2a2bb8-4bc4-369f-8321-fe16722a25f4', 'Ms Diaz.', true, 1, 'Title + last name: Ms works for any adult woman, married or not.'),
  ('90046833-6d0e-36a3-9703-ca6a43369db2', '6d2a2bb8-4bc4-369f-8321-fe16722a25f4', 'Ms Sara.', false, 2, 'Title + first name — the most common ESL transfer (common politeness pattern in es/ar/vi contexts, but not standard English).'),
  ('fc14dc72-4d08-3503-9d07-15b2d738dcdb', '6d2a2bb8-4bc4-369f-8321-fe16722a25f4', 'Teacher Sara.', false, 3, 'Occupation used as a title — direct transfer from classroom cultures where ''Teacher'' is a form of address.'),
  ('8a5aeb83-8ed4-351a-8649-b4d619f2a221', 'daec568d-13f6-37f2-94a0-bd89e8ed4c13', 'I speak English.', true, 1, 'Language names are proper nouns in English and always take a capital letter.'),
  ('a311efa7-1b6f-3533-9302-e99e669e483a', 'daec568d-13f6-37f2-94a0-bd89e8ed4c13', 'I speak english.', false, 2, 'Direct es transfer: Spanish writes languages lowercase (inglés, español) — English never does.'),
  ('a6a54f43-26d9-365f-bedd-4e603996154b', 'daec568d-13f6-37f2-94a0-bd89e8ed4c13', 'i speak English.', false, 3, 'Catches losing the sentence-start capital (and lowercase i), the other capitalization rule forms are graded on.'),
  ('5033f8ad-49bd-3067-a439-a77cb171e413', 'ad49dbc3-4a58-3f5b-b6a6-ae0e8106ee6e', 'doctor', true, 1, 'Heard after ''a'' — the job slot in the I''m-a frame.'),
  ('5545ba5f-69da-3e32-a421-81d2c367a472', 'ad49dbc3-4a58-3f5b-b6a6-ae0e8106ee6e', 'nurse', false, 2, 'Same medical association; catches topic-guessing instead of word-level listening.'),
  ('270a84fb-2d13-3061-87d9-acc4cf8dbbac', 'ad49dbc3-4a58-3f5b-b6a6-ae0e8106ee6e', 'waiter', false, 3, 'Ends in the same unstressed -er; catches suffix-only listening.'),
  ('b22d7358-499f-3cca-946e-6ad2da36f154', '59c8b73e-7985-3a99-a9de-78a293b0a9f3', 'I''m a doctor.', true, 1, 'The small word ''a'' is there — English always needs it before a job.'),
  ('2fb952ad-326f-3bb1-aa9a-261083a32ebd', '59c8b73e-7985-3a99-a9de-78a293b0a9f3', 'I''m doctor.', false, 2, 'Missing ''a''. Direct transfer from article-less frames (es ''Soy médico''); English requires the article.'),
  ('239ec1ff-2fd7-3289-9b47-db7626587555', '92019814-61fa-3af9-b4b4-2126ce39aeb4', 'pen', true, 1, 'Named after ''It''s a'' — the answer slot of What''s this?'),
  ('c531d42c-9a2e-3549-9a09-48a5562cd59c', '92019814-61fa-3af9-b4b4-2126ce39aeb4', 'bag', false, 2, 'Another taught object; forces word-level listening, not guessing.'),
  ('c7343e58-05a1-3d94-bdb9-1092ea0b51d9', '92019814-61fa-3af9-b4b4-2126ce39aeb4', 'this', false, 3, 'Catches learners who match the question word instead of the answer.'),
  ('54fed306-e9a5-3613-9131-8d0814cffde5', '293eff68-35b8-3a02-83a2-29eb62324550', 'That''s a chair.', true, 1, 'That IS a chair — the ''s is small but always there.'),
  ('89e9d46c-0b95-3c9d-82b9-51d8d3551b99', '293eff68-35b8-3a02-83a2-29eb62324550', 'That a chair.', false, 2, 'Missing ''s. Zero-copula transfer (zh/ar/vi drop ''is'' after this/that).'),
  ('272f38a9-b4d1-3f98-85f6-133e1b76c637', '293eff68-35b8-3a02-83a2-29eb62324550', 'That''s a table.', false, 3, 'Wrong object; keeps word-level listening honest while the grammar is in focus.'),
  ('06bdb9fd-dea3-3a8f-b2a5-396233ea377f', '987310d7-2775-3c12-afd1-34a82cc8b38e', '[L1: to hear it again]', true, 1, 'Sorry? plus repeat = please say it again.'),
  ('b0a55265-dec8-3a73-9eb4-13657355319f', '987310d7-2775-3c12-afd1-34a82cc8b38e', '[L1: to say sorry for a mistake]', false, 2, 'That is falling ''I''m sorry.'' — rising Sorry? asks, it does not apologize.'),
  ('a50f08fd-4b93-35b6-96f9-cf9dbf49c489', '987310d7-2775-3c12-afd1-34a82cc8b38e', '[L1: to hear the letters of a word]', false, 3, 'That is ''How do you spell that?'' — repeat and spell are different repair asks.'),
  ('d354f243-6c6b-3ba0-b50a-91b208cdfc35', 'eeaa45b7-573c-388b-8bf9-92cb57222624', '[L1: Say it again, please — I didn''t hear you.]', true, 1, 'Rising Sorry? is a repair ask, not an apology.'),
  ('6fb21c29-87c2-307c-9072-b944e115ee37', 'eeaa45b7-573c-388b-8bf9-92cb57222624', '[L1: I apologize.]', false, 2, 'The apology is falling ''I''m sorry.'' — the rise changes the meaning.'),
  ('329a1351-fb52-3641-9415-b3763ac0ec2d', '278b5be8-b82c-3a82-a75e-ac99064ed2ce', '[L1: different]', true, 1, '''this'' has the short i, ''these'' has the long ee — one sound, two words.'),
  ('7cc7b727-2a1b-3719-ae5b-98dc32d7c3a7', '278b5be8-b82c-3a82-a75e-ac99064ed2ce', '[L1: the same]', false, 2, 'If they sounded the same, the vowel length difference is not registering yet — replay at 0.75x.'),
  ('e4b840f5-9c89-3cc5-a9f5-557ee06fb1c3', '5ff46a4a-c550-3a58-b8a3-cac685a24f2f', '[L1: the end: -teen]', true, 1, '-teen has the long ee — that length is why -teen numbers are easy to hear.'),
  ('6cbc08af-78b4-378c-aaec-7868435de2f9', '5ff46a4a-c550-3a58-b8a3-cac685a24f2f', '[L1: the start: fif-]', false, 2, 'fif- has the short, quick i — if it sounded long, the two boxes are swapped.'),
  ('b781d2b0-5aba-39ab-9340-1033653d1d74', '737e439a-a230-3b40-bf0f-2f5a4fb6330f', '[L1: UP]', true, 1, 'Yes/no questions rise at the end — the rise says: answer yes or no.'),
  ('bb45e409-e0fb-3ca7-813f-d4a5fc0fd358', '737e439a-a230-3b40-bf0f-2f5a4fb6330f', '[L1: DOWN]', false, 2, 'Falling melody belongs to What/Where questions and statements.'),
  ('78f405bf-a4c7-3d24-acc2-eb78dd90d5cf', 'da37c0b0-551f-38ba-a8ac-7b68dee0e166', '[L1: DOWN]', true, 1, 'What/Where questions fall — the question word already marks the question.'),
  ('f105b0f9-aa20-31a6-88b8-021d3c17151b', 'da37c0b0-551f-38ba-a8ac-7b68dee0e166', '[L1: UP]', false, 2, 'Rising every question is the predicted transfer habit — WH-questions fall.'),
  ('c59830c1-8cc6-3ef7-8fb6-229923c3a79c', '20f209e3-cc7d-3077-b5c1-1c3d95ee6f04', '[L1: UP — say it again, please]', true, 1, 'Rising Sorry? asks for repetition, exactly as taught in L15.'),
  ('a14a4b5e-a1ad-3637-befe-eb82bf32a6f9', '20f209e3-cc7d-3077-b5c1-1c3d95ee6f04', '[L1: DOWN — I apologize]', false, 2, 'The falling version is the apology ''I''m sorry.'' — a different move.'),
  ('ed9332ac-7b29-32f6-8416-6bdee26c16f7', 'd5af696b-c21b-3fb4-ac69-8c50397649cf', 'She''s a nurse.', true, 1, 'After ''I''m a'' comes the job — the third frame answers the question.'),
  ('99ff2d7e-41a0-3d2f-b0aa-45258ecfe8de', 'd5af696b-c21b-3fb4-ac69-8c50397649cf', 'She''s from Brazil.', false, 2, 'That is her country: ''I''m from'' is the origin frame, not the job frame.'),
  ('ee604961-6867-3983-aeb2-c7137ac3c30b', 'd5af696b-c21b-3fb4-ac69-8c50397649cf', 'Her name is Nina.', false, 3, 'That is the name frame — plain ''I''m'' plus a name, no ''a'', no ''from''.'),
  ('8a196bf8-0285-331e-9cdf-134d07815173', '9c47d4a2-ce6b-3724-b1b3-08293a09ab8c', 'two-zero-one-four', true, 1, 'Digit by digit with grouping pauses — the pause marks where the group starts.'),
  ('ca270153-a76f-3ad6-be49-cde39d4fa4e4', '9c47d4a2-ce6b-3724-b1b3-08293a09ab8c', 'two-zero-four-one', false, 2, 'Last two digits flipped — order inside the group matters.'),
  ('b531f2e5-cdc8-311a-ae13-f659a140568d', '9c47d4a2-ce6b-3724-b1b3-08293a09ab8c', 'two-one-zero-four', false, 3, 'Middle digits swapped; the grouping pauses tell you where each number sits.')
INSERT INTO public.vocabulary (id, language, lemma, translation_l1, part_of_speech, frequency_rank, cefr_level, example_sentence, ipa) VALUES
  ('59c9c259-46bd-335f-a629-b29e3a43409e', 'en', 'hello', 'hola', 'interjection', NULL, 'A1', 'Hello! Nice day!', '/həˈloʊ/'),
  ('f1babde7-ff9f-39c6-8364-fb1aef14cbdd', 'en', 'hi', 'hola (informal)', 'interjection', NULL, 'A1', 'Hi! Good morning!', '/haɪ/'),
  ('b6978461-0bf3-36c4-83d5-2a77ced970cb', 'en', 'good morning', 'buenos días', 'chunk', NULL, 'A1', 'Good morning! Hello!', '/ˌɡʊd ˈmɔːrnɪŋ/'),
  ('4542472a-f57d-3c77-944f-4608450252fc', 'en', 'good evening', 'buenas noches (al llegar, para saludar)', 'chunk', NULL, 'A1', 'Good evening! Hello!', '/ˌɡʊd ˈiːvnɪŋ/'),
  ('a46b182c-c528-3c8f-b59e-d125097e977c', 'en', 'good night', 'buenas noches (al irse, para despedirse)', 'chunk', NULL, 'A1', 'Good night! See you!', '/ˌɡʊd ˈnaɪt/'),
  ('a69ebbe7-a8bd-3a57-b300-92c363e06a07', 'en', 'goodbye', 'adiós', 'interjection', NULL, 'A1', 'Goodbye! See you later!', '/ˌɡʊdˈbaɪ/'),
  ('fce118ac-8869-363d-960a-e1c285f5e6d6', 'en', 'bye', 'adiós (informal), chao', 'interjection', NULL, 'A1', 'Bye! See you!', '/baɪ/'),
  ('fe462d15-12ab-38b1-9654-8c048d3428da', 'en', 'See you later.', 'Hasta luego.', 'chunk', NULL, 'A1', 'Bye! See you later!', '/ˌsiː juː ˈleɪtər/'),
  ('113d5500-a0ff-3695-a8a0-47eaeb17ebde', 'en', 'letter', 'letra', 'noun', NULL, 'A1', 'B is a letter.', '/ˈletər/'),
  ('4fb055be-5166-3f24-9ad9-f4038934bba3', 'en', 'word', 'palabra', 'noun', NULL, 'A1', '''Hello'' is a word.', '/wɜːrd/'),
  ('13f529dc-a50f-3834-809b-f72952a3b77f', 'en', 'name', 'nombre', 'noun', NULL, 'A1', 'My name is Ana.', '/neɪm/'),
  ('1f3cbffe-fba8-3eb4-b43e-6cf9aca8ce8d', 'en', 'spell', 'deletrear', 'verb', NULL, 'A1', 'Spell your name: A-N-A.', '/spel/'),
  ('9b1b38aa-ece2-3830-aeb6-2d3b8ed000f8', 'en', 'nice', 'agradable', 'adjective', NULL, 'A1', 'Nice to meet you.', '/naɪs/'),
  ('98018cc3-fde6-39ce-9cc0-943b7498b082', 'en', 'meet', 'conocer (a alguien por primera vez)', 'verb', NULL, 'A1', 'Nice to meet you.', '/miːt/'),
  ('9cdff6fb-d780-3eac-b490-12bb221639dd', 'en', 'What''s your name?', '¿Cómo te llamas?', 'chunk', NULL, 'A1', 'Hello! What''s your name?', '/wʌts jɔːr ˈneɪm/'),
  ('84a5f1b6-5860-368a-879d-5ce52c519afa', 'en', 'My name is…', 'Me llamo… / Mi nombre es…', 'chunk', NULL, 'A1', 'My name is Ana.', '/maɪ ˈneɪm ɪz/'),
  ('26b226f2-f9e5-3c94-90ff-479b4022ec12', 'en', 'I''m…', 'Soy… (contracción de ''I am'')', 'chunk', NULL, 'A1', 'Hi! I''m Ana.', '/aɪm/'),
  ('09016548-61f2-321f-8985-e013db1460ae', 'en', 'Nice to meet you.', 'Mucho gusto.', 'chunk', NULL, 'A1', 'Nice to meet you, too.', '/ˌnaɪs tə ˈmiːt juː/'),
  ('f4229635-03f1-362f-8840-552b8b1742e8', 'en', 'zero', 'cero', 'number', NULL, 'A1', 'Zero, one, two, three.', '/ˈzɪroʊ/'),
  ('bb20f24e-862d-3867-a9f0-df3c2666781f', 'en', 'one', 'uno', 'number', NULL, 'A1', 'One name, one word.', '/wʌn/'),
  ('5672375c-d50a-3bd2-856f-7ca0fc65f983', 'en', 'two', 'dos', 'number', NULL, 'A1', 'Two letters: H, I.', '/tuː/'),
  ('12339fa4-e9e7-3285-a9aa-ccd662a34b8f', 'en', 'three', 'tres', 'number', NULL, 'A1', 'Three letters: B, Y, E.', '/θriː/'),
  ('e0f11386-1d24-380b-8507-391990b00856', 'en', 'four', 'cuatro', 'number', NULL, 'A1', 'Four letters: N, A, M, E.', '/fɔːr/'),
  ('de248d72-18fb-3214-882a-66737e5861bf', 'en', 'five', 'cinco', 'number', NULL, 'A1', 'Five, four, three, two, one.', '/faɪv/'),
  ('99d1f088-5bb2-3575-80a6-0dd0c37ed071', 'en', 'six', 'seis', 'number', NULL, 'A1', 'Six, seven, eight.', '/sɪks/'),
  ('17cb1476-b3f5-3187-8aed-bcaac1673bfa', 'en', 'seven', 'siete', 'number', NULL, 'A1', 'Seven, not eleven.', '/ˈsevən/'),
  ('191c659a-a299-39eb-82d5-f7e84990dca6', 'en', 'eight', 'ocho', 'number', NULL, 'A1', 'Eight, nine, ten.', '/eɪt/'),
  ('d999f8a0-db1a-3925-b979-e235639ff2fa', 'en', 'nine', 'nueve', 'number', NULL, 'A1', 'Nine, ten, eleven.', '/naɪn/'),
  ('fd36b1f7-7be8-30d2-9bac-d1a9512227dc', 'en', 'ten', 'diez', 'number', NULL, 'A1', 'Ten letters, two words.', '/ten/'),
  ('27b0365d-b3a4-3d56-b9e1-8fc21361db4d', 'en', 'eleven', 'once', 'number', NULL, 'A1', 'Eleven, not seven.', '/ɪˈlevən/'),
  ('d8757e93-8cb4-3040-a61e-957f7df88409', 'en', 'twelve', 'doce', 'number', NULL, 'A1', 'Twelve, not twenty.', '/twelv/'),
  ('0b3b40c0-289b-36a1-8d91-646d796a3ca3', 'en', 'thirteen', 'trece', 'number', NULL, 'A1', 'Thirteen, fourteen, fifteen.', '/ˌθɜːrˈtiːn/'),
  ('26070861-18f3-3a44-9333-6e8e20228166', 'en', 'fourteen', 'catorce', 'number', NULL, 'A1', 'Fourteen is four plus ten.', '/ˌfɔːrˈtiːn/'),
  ('8e2e56c8-095b-3651-aaef-f42079eb2c6a', 'en', 'fifteen', 'quince', 'number', NULL, 'A1', 'Fifteen, sixteen, seventeen.', '/ˌfɪfˈtiːn/'),
  ('88dfb2de-4dfb-39b5-a00b-09fb2b3aafa1', 'en', 'sixteen', 'dieciséis', 'number', NULL, 'A1', 'Sixteen is six plus ten.', '/ˌsɪksˈtiːn/'),
  ('606c0e91-9b60-3620-ae03-b6d763140ba2', 'en', 'seventeen', 'diecisiete', 'number', NULL, 'A1', 'Seventeen, eighteen, nineteen.', '/ˌsevənˈtiːn/'),
  ('a6bdff62-d5f2-3fd2-bb7f-96752b68f003', 'en', 'eighteen', 'dieciocho', 'number', NULL, 'A1', 'Eighteen is eight plus ten.', '/ˌeɪˈtiːn/'),
  ('424a9c10-2300-3ab0-972b-d88d7161851e', 'en', 'nineteen', 'diecinueve', 'number', NULL, 'A1', 'Nineteen, twenty.', '/ˌnaɪnˈtiːn/'),
  ('aebf2137-c075-33f2-a2fd-bb9420e6f84d', 'en', 'twenty', 'veinte', 'number', NULL, 'A1', 'Twenty is two times ten.', '/ˈtwenti/'),
  ('f7c2f629-7e30-3714-b27d-c9d62e1fc9f9', 'en', 'country', 'país', 'noun', NULL, 'A1', 'Mexico is a country.', '/ˈkʌntri/'),
  ('6a9c6672-5801-3fb2-97e1-0986cd878479', 'en', 'Where are you from?', '¿De dónde eres?', 'chunk', NULL, 'A1', 'Where are you from? I''m from Brazil.', '/ˌwer ər juː ˈfrʌm/'),
  ('8858f037-ffb0-33ee-8a0e-9ae4f25af039', 'en', 'I''m from…', 'Soy de…', 'chunk', NULL, 'A1', 'I''m from China.', '/aɪm frəm/'),
  ('d86d9b9a-92af-3b14-ab2c-b4e765416626', 'en', 'Mexico', 'México', 'noun', NULL, 'A1', 'She''s from Mexico.', '/ˈmeksɪkoʊ/'),
  ('cb9694b8-b090-3c58-814c-36ac39011375', 'en', 'Brazil', 'Brasil', 'noun', NULL, 'A1', 'I''m from Brazil.', '/brəˈzɪl/'),
  ('aa5249ec-dab7-3364-89fc-9dc1a7753559', 'en', 'China', 'China', 'noun', NULL, 'A1', 'I''m from China.', '/ˈtʃaɪnə/'),
  ('8feedb66-0e79-3622-9895-209b95f1f165', 'en', 'Vietnam', 'Vietnam', 'noun', NULL, 'A1', 'He''s from Vietnam.', '/ˌviːetˈnɑːm/'),
  ('70dcd839-5b27-3556-825a-6c8c8096b75c', 'en', 'Haiti', 'Haití', 'noun', NULL, 'A1', 'She''s from Haiti.', '/ˈheɪti/'),
