  ('9d36ba25-7806-35d9-b6c1-a402b3227e19', '3f844b10-3e35-30ed-b7f5-ca7abc358264', 7, 'cloze', 'A: I''m from Vancouver.  B: ___? Can you repeat that, please?', 0.5, 'productive', 'human-authored/phase0-slice', 'draft'),
