  ('8ce071e6-d5a7-3029-abbc-779ace481804', '3f844b10-3e35-30ed-b7f5-ca7abc358264', 9, 'dialogue', '[L1: Now speak. Meet your new AI classmate: 6-8 turns. Greet, exchange names, say where you are from, ask about jobs, and close the conversation. Use your repair phrases any time you need them.]', 0.7, 'productive', 'human-authored/phase0-slice', 'draft'),
